/**
 * Typed access to the Game SDK v1 (PRD §8.3).
 *
 * `vendor/dsh-game-sdk.js` is an offline bundle of `@dsh-game/sdk` generated by
 * `create-dsh-game`; it keeps the fully self-contained package constraint while
 * letting Vite bundle/inline the SDK together with the game.
 */

import { createGameSDK, isGameError } from '../vendor/dsh-game-sdk.js';
import type { Game } from '@dsh-game/sdk';

export type { Game };
export { createGameSDK, isGameError };

export function getGame(): Game {
  return createGameSDK();
}
